const fs=require('fs'); const {createRequire}=require('module'); const req=createRequire('/Users/dq/Documents/ERP/hub-erp-v0/server/package.json'); const sql=req('mssql'), bcrypt=req('bcryptjs');
const ROOT='/Users/dq/Documents/ERP/hub-erp-v0', API='http://localhost:3002/api'; const RUN=`P1DEF001-${Date.now()}`; const ev={runTag:RUN,checks:[],defects:[]};
function add(id,ok,detail){const it={id,status:ok?'PASS':'FAIL',detail,at:new Date().toISOString()}; ev.checks.push(it); if(!ok)ev.defects.push(it); console.log(`${ok?'✅':'❌'} ${id}`)}
function env(){const o={}; for(const l of fs.readFileSync(ROOT+'/server/.env','utf8').split(/\r?\n/)){const m=l.match(/^([^#=]+)=(.*)$/); if(m)o[m[1].trim()]=m[2].trim()} return o}
async function api(p,opt={}){const r=await fetch(API+p,{...opt,headers:{'content-type':'application/json',authorization:'Bearer '+global.token,...(opt.headers||{})}}); const t=await r.text(); let j; try{j=t?JSON.parse(t):null}catch{j=t} if(!r.ok){const e=new Error(j?.message||t); e.status=r.status; e.body=j; throw e} return j?.data||j}
async function insert(pool,t,o){const cols=Object.keys(o), rq=pool.request(); cols.forEach(c=>rq.input(c,o[c])); return (await rq.query(`insert into ${t} (${cols.map(c=>'['+c+']').join(',')}) output inserted.id values (${cols.map(c=>'@'+c).join(',')})`)).recordset[0].id}
async function db(pool,q,i={}){const r=pool.request(); for(const [k,v] of Object.entries(i))r.input(k,v); return (await r.query(q)).recordset}
async function prep(pool){const s=RUN.slice(-8), now=new Date(), common={created_at:now,updated_at:now,is_deleted:0}; const pw='Pwd_'+s; await insert(pool,'sys_user',{username:'u_'+s,password:bcrypt.hashSync(pw,10),real_name:'P1DEF',email:'',phone:'',dept_id:null,emp_id:null,avatar:'',status:1,...common}); const login=await fetch(API+'/auth/login',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({username:'u_'+s,password:pw})}).then(r=>r.json()); global.token=login.data.accessToken; const supplierId=await insert(pool,'master_supplier',{supplier_code:'S_'+s,supplier_name:'供应商_'+s,short_name:'S_'+s,supplier_type:1,contact_person:'',contact_phone:'',email:'',address:'',payment_term_id:null,buyer_id:null,tax_number:'',bank_name:'',bank_account:'',status:1,remark:RUN,...common}); const wh=await insert(pool,'master_warehouse',{warehouse_code:'W_'+s,warehouse_name:'仓_'+s,warehouse_type:1,parent_id:null,manager_id:null,address:'',is_default:0,status:1,remark:RUN,...common}); const unit=await insert(pool,'master_unit',{unit_code:'U_'+s,unit_name:'个',unit_type:1,precision:4,status:1,remark:RUN,...common}); const mat=await insert(pool,'master_material',{material_code:'M_'+s,material_name:'物料_'+s,material_spec:'',category_id:null,unit_id:unit,material_type:2,purchase_type:1,barcode:'',default_warehouse:wh,safety_stock:0,min_order_qty:0,lead_time:0,standard_cost:0,sale_price:0,is_batch_manage:0,is_serial_manage:0,shelf_life_days:0,status:1,remark:RUN,...common}); const cur=await insert(pool,'master_currency',{currency_code:'C'+s.slice(0,5),currency_name:'币_'+s,currency_symbol:'¥',exchange_rate:1,is_base:0,status:1,remark:RUN,...common}); const pt=await insert(pool,'master_payment_term',{term_code:'PT_'+s,term_name:'月结_'+s,term_type:3,credit_days:30,advance_ratio:0,stage1_ratio:0,stage2_ratio:0,stage3_ratio:0,status:1,remark:RUN,...common}); return {supplierId: supplierId, warehouseId: wh, unitId: unit, materialId: mat, currencyId: cur, paymentTermId: pt, orgId:'org-'+s}}
async function inbound(ctx,qty=10){const pr=await api('/purchase-requests',{method:'POST',body:JSON.stringify({orgId:ctx.orgId,requestDate:'2026-07-20',remark:RUN,entries:[{materialId:ctx.materialId,materialCode:'M',materialName:'MAT',unitId:ctx.unitId,unitName:'个',requestQty:qty,estimatedPrice:10,purchaseOrgId:ctx.orgId,supplierId:ctx.supplierId,warehouseId:ctx.warehouseId}]})}); await api(`/purchase-requests/${pr.id}/submit`,{method:'POST'}); const pra=await api(`/purchase-requests/${pr.id}/approve`,{method:'POST'}); const po=await api('/purchase-orders/from-request',{method:'POST',body:JSON.stringify({idempotencyKey:RUN+'po'+Math.random(),supplierId:ctx.supplierId,contractNo:'HT'+RUN,orderDate:'2026-07-20',currencyId:ctx.currencyId,paymentTermId:ctx.paymentTermId,lines:[{requestEntryId:pra.entries[0].id,quantity:qty,unitPrice:10,taxRate:13,warehouseId:ctx.warehouseId,checkIncoming:false}]})}); await api(`/purchase-orders/${po.id}/submit`,{method:'POST'}); const poa=await api(`/purchase-orders/${po.id}/approve`,{method:'POST'}); const rn=await api('/purchase-receive-notices/from-order',{method:'POST',body:JSON.stringify({purchaseOrderId:po.id,stockOrgId:ctx.orgId,purchaseOrgId:ctx.orgId,receiveBatchNo:RUN+'rb'+Math.random(),needCheck:false,lines:[{orderEntryId:poa.entries[0].id,quantity:qty,checkIncoming:false,warehouseId:ctx.warehouseId}]})}); await api(`/purchase-receive-notices/${rn.id}/submit`,{method:'POST'}); const rna=await api(`/purchase-receive-notices/${rn.id}/approve`,{method:'POST'}); const inv=await api('/inventory-in/from-receive-notices',{method:'POST',body:JSON.stringify({idempotencyKey:RUN+'in'+Math.random(),settleOrgId:ctx.orgId,ownerType:'BD_OwnerOrg',ownerId:ctx.orgId,entries:[{sourceReceiveNoticeEntryId:rna.entries[0].id,quantity:qty,warehouseId:ctx.warehouseId}]})}); await api(`/inventory-in/${inv.id}/submit`,{method:'POST'}); const ina=await api(`/inventory-in/${inv.id}/approve`,{method:'POST',body:JSON.stringify({approvedBy:'P1DEF'})}); return {inbound:ina,entry:ina.entries[0]}}
(async()=>{const e=env(); const pool=await sql.connect({server:e.DB_MSSQL_HOST||'localhost',port:+(e.DB_MSSQL_PORT||1433),user:e.DB_MSSQL_USERNAME,password:e.DB_MSSQL_PASSWORD,database:e.DB_MSSQL_DATABASE,options:{encrypt:false,trustServerCertificate:true}}); try{const ctx=await prep(pool); const src=await inbound(ctx,12); const key='RR-IDEM-'+RUN; const body=(qty,reason)=>({inventoryInId:src.inbound.id,idempotencyKey:key,returnMode:'REPLENISH',reason,requestDate:'2026-07-20',lines:[{inventoryInEntryId:src.entry.id,quantity:qty}]}); const a=await api('/purchase-return-requests/from-inbound',{method:'POST',body:JSON.stringify(body(1,'同载荷'))}); const b=await api('/purchase-return-requests/from-inbound',{method:'POST',body:JSON.stringify(body(1,'同载荷'))}); add('P1-TC-006A',a.id===b.id,{a:a.id,b:b.id}); try{await api('/purchase-return-requests/from-inbound',{method:'POST',body:JSON.stringify(body(2,'不同载荷'))}); add('P1-TC-006B',false,{message:'未返回冲突'});}catch(err){add('P1-TC-006B',err.status===400&&/幂等键/.test(err.message),{status:err.status,message:err.message});} const rows=await db(pool,'select id,request_no,idempotency_key,payload_hash from biz_purchase_return_request where idempotency_key=@k',{k:key}); add('P1-DB-001',rows.length===1&&!!rows[0].payload_hash,{rows}); const src2=await inbound(ctx,20); const cbody=(qty)=>({inventoryInId:src2.inbound.id,idempotencyKey:'RR-CONC-'+RUN,returnMode:'REPLENISH',reason:'并发',lines:[{inventoryInEntryId:src2.entry.id,quantity:qty}]}); const res=await Promise.allSettled([api('/purchase-return-requests/from-inbound',{method:'POST',body:JSON.stringify(cbody(1))}),api('/purchase-return-requests/from-inbound',{method:'POST',body:JSON.stringify(cbody(2))})]); add('P1-TC-006C',res.filter(x=>x.status==='fulfilled').length===1&&res.filter(x=>x.status==='rejected'&&x.reason.status===400).length===1,{results:res.map(x=>x.status==='fulfilled'?{ok:true,id:x.value.id}:{ok:false,status:x.reason.status,message:x.reason.message})});} finally {await pool.close(); ev.summary={total:ev.checks.length,pass:ev.checks.filter(x=>x.status==='PASS').length,fail:ev.checks.filter(x=>x.status==='FAIL').length}; fs.writeFileSync(ROOT+'/采购模块P1-DEF-001复验证据-20260720.json',JSON.stringify(ev,null,2)); console.log('EVIDENCE='+ROOT+'/采购模块P1-DEF-001复验证据-20260720.json'); console.log(JSON.stringify(ev.summary)); if(ev.summary.fail)process.exitCode=2;}})().catch(e=>{ev.fatal=String(e.stack||e);fs.writeFileSync(ROOT+'/采购模块P1-DEF-001复验证据-20260720.json',JSON.stringify(ev,null,2));console.error(e);process.exit(1)});
